import math

def solve():
    good_numbers = set()
    for g in range(2, 100):
        for a in range(1, 100):
            for b in range(a + 1, 100):
                if math.gcd(a, b) == 1:
                    m = g**2 * (a**2 + b**2)
                    good_numbers.add(m)

    sorted_good_numbers = sorted(list(good_numbers))
    for i, m in enumerate(sorted_good_numbers):
        print(f"{i+1}: {m}")

solve()
